// Reads the customer's message and decides the intent with keyword rules.
// Highest priority first; the first match wins. No match = NONE (unclear message).

const message = String($('Receive Customer Message').first().json.chatInput || '');
const text = message.toLowerCase().trim();

const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// A keyword must START at a word boundary: "ship" matches "shipping" but not "friendship"
const has = w => new RegExp('\\b' + esc(w)).test(text);

// An email address (if the message has one) and an order number (if it has one)
const emailMatch = message.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
const email = emailMatch ? emailMatch[0] : '';
const found = text.match(/(?:order\s*(?:number\s*)?#?\s*|#)(\d{4,6})\b|^(\d{4,6})$/);
const order_number = found ? (found[1] || found[2]) : '';

const rules = [
  {
    intent: 'HUMAN',
    regex: /\b(human|real person|live agent|representative|supervisor|manager)\b|\b(talk|speak|chat) (to|with) (a |an |the |your )?(person|someone|somebody|agent|human|rep|staff|team)\b|\bcall me\b/
  },
  {
    intent: 'COMPLAINT',
    words: [
      'broken', 'damaged', 'defective', 'faulty', 'fell apart', 'came off',
      'ripped', 'torn', 'not working', 'wrong size', 'wrong item',
      'wrong color', 'wrong pair', 'unacceptable', 'terrible', 'awful',
      'horrible', 'worst', 'angry', 'furious', 'annoyed', 'upset',
      'disappointed', 'unhappy', 'not happy', 'ridiculous', 'scam',
      'money back', 'want a refund', 'need a refund', 'no response', 'ignored'
    ]
  },
  {
    intent: 'ORDER',
    words: ['my order', 'order status', 'order number', 'tracking', 'track my', 'my parcel', 'my package']
  },
  {
    intent: 'FAQ',
    words: [
      'ship', 'deliver', 'postage', 'return', 'exchange', 'refund', 'warranty',
      'policy', 'hours', 'opening', 'open', 'what time', 'pay', 'paypal',
      'credit card', 'visa', 'mastercard', 'send back', 'send it back',
      'send them back', 'send my shoes back'
    ]
  },
  {
    intent: 'PRODUCT',
    words: [
      'shoe', 'sneaker', 'boot', 'sandal', 'slipper', 'slip-on', 'trainer',
      'running', 'basketball', 'casual', 'training', 'size', 'color', 'colour',
      'in stock', 'price', 'how much', 'cheap', 'budget', 'recommend',
      'looking for', 'do you have', 'do you sell', 'nike', 'adidas', 'puma',
      'reebok', 'converse', 'vans', 'new balance', 'asics', 'hoka', 'brooks',
      'skechers'
    ],
    regex: /\b(men|mens|women|womens|kids|boys|girls)\b/   // answers like "men's" or "for kids"
  }
];

let intent = 'NONE';
let matched = '';

// 1) A short message containing an email address = the customer is leaving contact details
const wordCount = message.replace(email, ' ').trim().split(/\s+/).filter(Boolean).length;
if (email && wordCount <= 6) { intent = 'EMAIL'; matched = email; }

// 2) Keyword rules, in priority order
if (intent === 'NONE') {
  for (const rule of rules) {
    let hit = (rule.words || []).find(w => has(w));
    if (!hit && rule.regex) { const r = text.match(rule.regex); if (r) hit = r[0]; }
    if (!hit && rule.intent === 'ORDER' && order_number) hit = 'order number ' + order_number;   // a bare order number counts too
    if (hit) { intent = rule.intent; matched = hit; break; }
  }
}

// 3) Short greetings or thanks, only if nothing else matched
const smalltalk = /^(hi|hello|hey|hiya|good (morning|afternoon|evening)|thanks|thank you|thx|ok|okay|bye|goodbye)\b/;
if (intent === 'NONE' && text.length <= 25 && smalltalk.test(text)) { intent = 'SMALLTALK'; matched = 'greeting or thanks'; }

return [{ json: { message, intent, matched, order_number, email } }];

