// Looks up the order the customer asked about and writes the reply in code (no AI),
// so order details can never be invented.

const detected = $('Detect Intent by Rules').first().json;
const orderNumber = String(detected.order_number || '').trim();
const rows = items.map(item => item.json);

function prettyDate(s) {
  const d = new Date(String(s).trim() + 'T00:00:00');
  return isNaN(d) ? String(s) : d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

let reply = '';
let action = '';
let needs_human = false;

if (!orderNumber) {
  reply = 'I can check that for you. What is your order number? You can find it in your confirmation email.';
  action = 'Asked for order number';
} else {
  const order = rows.find(r => String(r['Order ID'] ?? '').trim() === orderNumber);

  if (!order) {
    reply = `I could not find an order with number ${orderNumber}. Could you double-check it? It is in your confirmation email.`;
    action = 'Order not found';
  } else {
    const status = String(order['Status'] || '').trim().toLowerCase();
    const product = order['Product'];
    const eta = order['Estimated Delivery'] ? prettyDate(order['Estimated Delivery']) : '';
    const tracking = order['Tracking Number'];
    action = 'Order status given';

    if (status === 'processing') {
      reply = `Order #${orderNumber} (${product}) is being prepared for shipping.` + (eta ? ` Estimated delivery: ${eta}.` : '');
    } else if (status === 'shipped') {
      reply = `Good news, order #${orderNumber} (${product}) has shipped.` + (tracking ? ` Tracking number: ${tracking}.` : '') + (eta ? ` Estimated delivery: ${eta}.` : '');
    } else if (status === 'out for delivery') {
      reply = `Order #${orderNumber} (${product}) is out for delivery and should arrive today.`;
    } else if (status === 'delivered') {
      reply = `Order #${orderNumber} (${product}) is marked as delivered. If you cannot find it, tell me and I will pass it to our team.`;
    } else if (status === 'cancelled') {
      reply = `Order #${orderNumber} (${product}) was cancelled. If that is a surprise, tell me and I will pass it to our team.`;
    } else if (status === 'delayed') {
      reply = `Order #${orderNumber} (${product}) is delayed, and I am sorry about that.` + (tracking ? ` Tracking number: ${tracking}.` : '') + ' I have passed this to our team.';
      action = 'Delayed order flagged';
      needs_human = true;
    } else {
      reply = `I found order #${orderNumber}, but I want a teammate to confirm its status, so I will pass this to our team.`;
      action = 'Handed off';
      needs_human = true;
    }
  }
}

return [{ json: { reply, action, needs_human, ticket_type: 'Handoff', order_number: orderNumber } }];

// Every branch ends here. This node:
// 1. fills in anything a branch did not provide,
// 2. makes a ticket reference when a human is needed,
// 3. adds the "what happens next" text to the reply,
// 4. cleans customer text before it goes to Sheets and Slack.

const item = items[0].json;
const detected = $('Detect Intent by Rules').first().json;
const trigger = $('Receive Customer Message').first().json;
const config = $('Load Config').first().json;

// The AI only runs for messages the keyword rules could not place
const ai = $('Parse AI Intent').isExecuted ? $('Parse AI Intent').first().json : null;
const finalIntent = ai ? ai.intent : detected.intent;
const intent = finalIntent === 'NONE' ? 'OTHER' : finalIntent;
const routed_by = ai ? ai.matched
  : detected.intent === 'EMAIL' ? 'rule: email address'
  : detected.matched ? 'rule: ' + detected.matched : 'no rule matched';

const noReply = !item.reply;   // a branch that forgot to write a reply becomes a handoff
const needs_human = noReply || item.needs_human === true || item.needs_human === 'true';
const ticket_type = item.ticket_type || 'Handoff';
const order_number = item.order_number || detected.order_number || '';

// Customer text is untrusted: Sheets treats a leading = + - @ as a formula
const safe = t => /^[=+\-@]/.test(t) ? "'" + t : t;
const rawMessage = String(trigger.chatInput || '');
const message = safe(rawMessage);
const customer_email = safe(detected.email || '');

let reply = item.reply || 'Sorry, something went wrong on my side.';

let ticket_id = '';
let slack_text = '';
if (needs_human) {
  const now = new Date();
  const day = now.toISOString().slice(2, 10).replace(/-/g, '');
  ticket_id = 'T-' + day + '-' + String(now.getTime()).slice(-5);

  // Ask for an email only if the customer has not given one yet
  if (ticket_type !== 'Email') {
    reply += ' Your reference is ' + ticket_id + '.' + (detected.email
      ? ' We will reply to ' + detected.email + '.'
      : ' If you would like a reply by email, type your email address here.');
  }

  // Slack treats & < > as special characters, so escape them
  const slackSafe = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const heading = ticket_type === 'Complaint' ? ':rotating_light: New complaint '
    : ticket_type === 'Email' ? ':email: Customer left an email '
    : ':raising_hand: Customer needs a human ';
  slack_text = heading + ticket_id
    + '\nOrder: ' + (order_number || '-')
    + '\nEmail: ' + (detected.email ? slackSafe(detected.email) : '-')
    + '\nCustomer said: ' + slackSafe(rawMessage)
    + '\nRouted by: ' + slackSafe(routed_by)
    + '\nTickets sheet: https://docs.google.com/spreadsheets/d/' + config.sheet_id;
}

const action = noReply ? 'Error: no reply from branch'
  : item.action || (needs_human ? (ticket_type === 'Complaint' ? 'Ticket created' : ticket_type === 'Email' ? 'Email saved' : 'Handed off') : 'Answered');

return [{ json: {
  timestamp: new Date().toISOString(),
  session_id: trigger.sessionId,
  message, intent, routed_by, action, needs_human, ticket_type, ticket_id, order_number, customer_email, reply, slack_text
} }];

// PRODUCT branch: finds shoes in the catalog that match the customer's message.
// No AI here: names, prices, sizes and colors come straight from the Products tab,
// so nothing can be invented.

const message = String($('Receive Customer Message').first().json.chatInput || '');
const text = message.toLowerCase();
const rows = items.map(i => i.json).filter(r => r['Product Name']);

// ---- small helpers ----
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const hasWord = (t, w) => new RegExp('\\b' + esc(w) + '\\b').test(t);
const lc = v => String(v || '').trim().toLowerCase();
const split = v => String(v || '').split(',').map(s => s.trim()).filter(Boolean);
const unique = a => [...new Set(a)];
const price = r => Number(String(r['Price']).replace(/[^0-9.]/g, ''));

// ---- what the catalog knows (read from the sheet, not hard-coded) ----
const brands = unique(rows.map(r => String(r['Brand']).trim()).filter(Boolean));
const categories = unique(rows.map(r => String(r['Category']).trim()).filter(Boolean));
const colors = unique(rows.flatMap(r => String(r['Colors Available'] || '').split(/[,/]/).map(lc).filter(Boolean)));

// ---- what the customer asked for ----
let gender = '';
if (/\b(women|womens|woman|ladies|lady|female|girlfriend|wife|mom|mother)\b/.test(text)) gender = 'Women';
else if (/\b(kid|kids|child|children|boy|boys|girl|girls|son|daughter|toddler|youth)\b/.test(text)) gender = 'Kids';
else if (/\b(men|mens|man|guy|guys|male|husband|dad|father)\b/.test(text)) gender = 'Men';

const synonyms = { running: ['run', 'runner', 'runners', 'jogging'], basketball: ['hoops'], training: ['gym', 'workout'], casual: ['everyday', 'lifestyle'] };
const category = categories.find(c => hasWord(text, lc(c)) || (synonyms[lc(c)] || []).some(w => hasWord(text, w))) || '';
const brand = brands.find(b => hasWord(text, lc(b))) || '';
const color = colors.find(c => hasWord(text, c)) || '';

const sizeMatch = text.match(/\b(?:size|sz|us)\s*(\d{1,2}(?:\.5)?)\b/);
const size = sizeMatch ? sizeMatch[1] : '';

let minPrice = null, maxPrice = null, minStrict = false, maxStrict = false, m;
if ((m = text.match(/between\s*\$?\s*(\d{2,4})\s*(?:and|to|-)\s*\$?\s*(\d{2,4})/))) { minPrice = +m[1]; maxPrice = +m[2]; }
else if ((m = text.match(/(under|below|less than|cheaper than|up to|no more than|budget(?: of| is)?)\s*\$?\s*(\d{2,4})/))) {
  maxPrice = +m[2]; maxStrict = /^(under|below|less than|cheaper than)/.test(m[1]);   // "under 100" excludes exactly 100
}
else if ((m = text.match(/(over|above|more than|at least|minimum)\s*\$?\s*(\d{2,4})/))) {
  minPrice = +m[2]; minStrict = /^(over|above|more than)/.test(m[1]);
}

// ---- is the customer asking about one specific model? ----
// Remove size and price phrases first, so their numbers are not mistaken for model numbers
const nameText = text
  .replace(/\b(?:size|sz|us)\s*\d{1,2}(?:\.5)?\b/g, ' ')
  .replace(/(?:between|under|below|less than|up to|cheaper than|no more than|budget(?: of| is)?|over|above|more than|at least|minimum)\s*\$?\s*\d{2,4}(?:\s*(?:and|to|-)\s*\$?\s*\d{2,4})?/g, ' ');
const msgWords = new Set(nameText.split(/[^a-z0-9]+/).filter(Boolean));
const filterWords = new Set([brand, category, color].join(' ').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean));
const wordsOf = name => unique(lc(name).split(/[^a-z0-9]+/).filter(Boolean));

// how many different product names contain each word
const freq = {};
unique(rows.map(r => lc(r['Product Name']))).forEach(n => wordsOf(n).forEach(w => { freq[w] = (freq[w] || 0) + 1; }));

// A model counts as named if 2+ of its words are in the message, or 1 word that at most
// 3 product names contain (4+ letters, or a 2+ digit number). The 1-word rule is skipped when the
// customer also named a category ("light running shoes" is a search, not a model).
const scored = rows.map(r => {
  const hits = wordsOf(r['Product Name']).filter(w => (w.length >= 3 || /^\d+$/.test(w)) && msgWords.has(w) && !filterWords.has(w));
  const rare = !category && hits.some(w => freq[w] <= 3 && (w.length >= 4 || /^\d{2,}$/.test(w)));
  return { r, n: hits.length, ok: hits.length >= 2 || rare };
}).filter(x => x.ok);
const top = scored.length ? Math.max(...scored.map(x => x.n)) : 0;
let named = scored.filter(x => x.n === top).map(x => x.r);

// ---- filters ----
const matchesGender = r => !gender || lc(r['Gender']) === lc(gender);
const matchesSize = r => !size || split(r['Sizes Available']).some(s => parseFloat(s) === parseFloat(size));
const matchesColor = r => !color || String(r['Colors Available'] || '').split(/[,/]/).map(lc).includes(color);

function describe(r) {
  return `- ${r['Product Name']} (${r['Brand']}, ${r['Gender']} ${r['Category']}) - $${r['Price']}. Sizes: ${split(r['Sizes Available']).join(', ')}. Colors: ${split(r['Colors Available']).join(', ')}.`;
}

let reply = '';
let action = '';

if (named.length) {
  // A specific model: show it and say whether the requested size/color exists
  if (gender) { const g = named.filter(matchesGender); if (g.length) named = g; }
  const shown = named.slice(0, 3).map(r => {
    let line = describe(r);
    if (size) line += matchesSize(r) ? ` Size ${size} is available.` : ` Size ${size} is not available.`;
    if (color) line += matchesColor(r) ? ` It comes in ${color}.` : ` It is not available in ${color}.`;
    return line;
  });
  reply = (named.length > 3 ? `I found ${named.length} matches. Here are 3:\n` : shown.length === 1 ? 'Here is what I found:\n' : 'Here are the closest matches:\n') + shown.join('\n');
  if (named.length > 3) reply += '\n\nTo narrow it down, send who it is for, size and color in one message, for example: "Pegasus for women in size 8".';
  action = 'Product info given';

} else if (gender || category || brand || color || size || minPrice !== null || maxPrice !== null) {
  // Search by filters, cheapest first
  const results = rows.filter(r =>
    matchesGender(r) && matchesSize(r) && matchesColor(r) &&
    (!category || lc(r['Category']) === lc(category)) &&
    (!brand || lc(r['Brand']) === lc(brand)) &&
    (minPrice === null || (minStrict ? price(r) > minPrice : price(r) >= minPrice)) &&
    (maxPrice === null || (maxStrict ? price(r) < maxPrice : price(r) <= maxPrice))
  ).sort((a, b) => price(a) - price(b));

  if (results.length === 0) {
    const genderText = { Men: "men's", Women: "women's", Kids: "kids'" }[gender] || '';
    const wanted = [brand, genderText, category.toLowerCase(), 'shoes',
      size ? 'in size ' + size : '', color ? 'in ' + color : '',
      maxPrice !== null ? 'under $' + maxPrice : '', minPrice !== null ? 'over $' + minPrice : ''].filter(Boolean).join(' ');
    reply = `I could not find an exact match for ${wanted}. Try a different size, color or budget, or ask me about a specific model.`;
    action = 'No product match';
  } else {
    const shown = results.slice(0, 3).map(describe);
    reply = (results.length > 3 ? `I found ${results.length} options. Here are 3 to start with:\n` : 'Here is what I found:\n') + shown.join('\n');
    if (results.length > 3) reply += '\n\nTo narrow it down, send everything in one message, for example: "Nike running shoes size 10 under $120".';
    action = 'Product info given';
  }

} else {
  reply = `I would be happy to help you find shoes! Who are they for (men, women or kids), and what kind: ${categories.join(', ')}? You can also tell me a brand, color, size or budget.`;
  action = 'Asked for product details';
}

return [{ json: { reply, action, needs_human: false, order_number: '' } }];

// Turns the AI's answer into an intent. The AI only proposes:
// it is trusted only with a valid label AND HIGH confidence, otherwise the message becomes OTHER (handoff).

const data = items[0].json;
const answer = String(data.message?.content ?? data.choices?.[0]?.message?.content ?? '').trim();
const detected = $('Detect Intent by Rules').first().json;

// Small models do not always follow the format exactly ("INTENT: ORDER" or just "ORDER"),
// so look for the label word and the HIGH/LOW word anywhere in the answer.
const upper = answer.toUpperCase();
const aiIntent = (upper.match(/\b(PRODUCT|ORDER|COMPLAINT|FAQ|OTHER)\b/) || [])[1] || '';
const confidence = (upper.match(/\b(HIGH|LOW)\b/) || [])[1] || '';

const accepted = ['PRODUCT', 'ORDER', 'COMPLAINT', 'FAQ'].includes(aiIntent) && confidence === 'HIGH';

return [{ json: {
  ...detected,
  intent: accepted ? aiIntent : 'OTHER',
  matched: 'AI says ' + (aiIntent || 'nothing') + ' ' + (confidence || '-'),
  ai_answer: answer.replace(/\s+/g, ' ')
} }];

// Builds the owner's daily summary from the Conversations and Tickets tabs.
// No AI here: every number comes straight from the sheet.

const config = $('Load Config').first().json;
const hours = Number(config.summary_hours) || 24;
const since = Date.now() - hours * 60 * 60 * 1000;

const convs = $('Load Conversations').all().map(i => i.json)
  .filter(r => r['Timestamp'] && new Date(r['Timestamp']).getTime() >= since);
const tickets = $('Load Tickets').all().map(i => i.json).filter(r => r['Ticket ID']);
const newTickets = tickets.filter(r => new Date(r['Created At']).getTime() >= since);
const openTickets = tickets
  .filter(r => String(r['Status'] || '').trim().toLowerCase() === 'open')
  .sort((a, b) => new Date(b['Created At']) - new Date(a['Created At']));

// ---- helpers ----
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');   // Slack special characters
const short = (s, n) => {
  const t = String(s || '').replace(/^'/, '').replace(/\s+/g, ' ').trim();   // the leading ' is our formula guard
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};
const countBy = (rows, key) => rows.reduce((o, r) => {
  const k = String(r[key] || 'Other').trim();
  o[k] = (o[k] || 0) + 1;
  return o;
}, {});
const nice = k => k.toUpperCase() === 'FAQ' ? 'FAQ' : k.charAt(0).toUpperCase() + k.slice(1).toLowerCase();
const listCounts = o => Object.entries(o).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${nice(k)} ${v}`).join(', ');

// ---- numbers ----
const total = convs.length;
const chats = new Set(convs.map(r => r['Session ID'])).size;
const escalated = convs.filter(r => /handed off|ticket created|flagged|error/i.test(String(r['Action'] || ''))).length;
const automated = total - escalated;
const pct = total ? Math.round(automated / total * 100) : 0;

// ---- most common questions (product, order and FAQ messages, grouped by their text) ----
const normalize = s => String(s || '').toLowerCase().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').trim();
const groups = {};
convs
  .filter(r => ['FAQ', 'PRODUCT', 'ORDER'].includes(String(r['Intent']).toUpperCase()))
  .forEach(r => {
    const key = normalize(r['Customer Message']);
    if (!key) return;
    groups[key] = groups[key] || { text: r['Customer Message'], n: 0 };
    groups[key].n++;
  });
const top = Object.values(groups).sort((a, b) => b.n - a.n).slice(0, 3);

// ---- the message ----
const lines = [`:bar_chart: *Support summary, last ${hours === 24 ? '24 hours' : hours + ' hours'}*`];
if (total === 0) {
  lines.push('No customer messages in this period.');
} else {
  lines.push(`Messages: ${total} in ${chats} chat${chats === 1 ? '' : 's'}`);
  lines.push(`Answered automatically: ${automated} (${pct}%) | Passed to a human: ${escalated}`);
  lines.push(`By topic: ${listCounts(countBy(convs, 'Intent'))}`);
}
lines.push(`New tickets: ${newTickets.length}` + (newTickets.length ? ` (${listCounts(countBy(newTickets, 'Type'))})` : ''));
lines.push(`Open tickets now: ${openTickets.length}`);
if (top.length) {
  lines.push('', '*Top questions*');
  top.forEach(q => lines.push(`- "${esc(short(q.text, 60))}" (${q.n})`));
}
if (openTickets.length) {
  lines.push('', '*Open tickets, newest first*');
  openTickets.slice(0, 5).forEach(t => lines.push(`- ${t['Ticket ID']} (${t['Type']}): ${esc(short(t['Message'], 60))}`));
}
lines.push('', `Tickets sheet: https://docs.google.com/spreadsheets/d/${config.sheet_id}`);

return [{ json: { summary_text: lines.join('\n') } }];

const data = items[0].json;
const response = String(data.message?.content ?? data.choices?.[0]?.message?.content ?? '').trim();

// Remove any greeting or sign-off the model added anyway
const cleaned = response
  .replace(/^(Dear|Hi|Hello|Hey)\b[^.!?\n]{0,30}[.!?]\s*/i, '')
  .replace(/\n*\b(Best regards|Sincerely|Warm regards|Kind regards)\b[\s\S]*$/i, '')
  .replace(/\s+/g, ' ')
  .trim();

// The AI was told to say NOT_SURE when STORE INFO has no answer
const needs_human = cleaned === '' || /NOT[_\s]?SURE/i.test(response);

const reply = needs_human
  ? 'Good question! I want to be sure you get the right answer, so I will pass this to our team.'
  : cleaned;

return [{ json: { reply, needs_human } }];
